WINTER_SPRING = ["season:winter", "season:spring"]
LUNAR = ["holiday:lunar-new-year", "season:winter"]

PACK = [
    # ---------------- Seasons, just teens (seasons age-13/14 primary 6 -> 7) ----------------
    A("cold-stratification-seed-bank", "Cold Stratification Seed Bank",
      "Teens give native seeds the winter they require: labelled jars of cold, damp weeks, logged chill, and a spring germination test that grades the bank.",
      ["seasons"], (13, 14), (4, 14), (40, 55), ["indoor"],
      ["native or perennial seed that genuinely needs cold to germinate, chosen with a trusted seed supplier's or botanic reference's word on each kind (the bank's founding list — kinds whose packets or references state a cold period, with the stated weeks copied onto the bank's cards exactly)", "small jars or sealable pots, one per kind per batch, with damp sand or vermiculite as the cold bed (damp as a wrung cloth, never wet — the seed sleeps in the damp, it does not swim in it)", "labels that survive the fridge, a marker that writes on them cold, and the bank book (a hardback ledger: kind, source, date in, weeks required, date due out, and the spring test's verdict — the bank's whole memory)", "a fridge shelf or cold frame agreed with the adults in advance (the bank's vault — a shelf that will not be cleared in a tidy-up, at a cold that stays cold, for the whole stated term)"],
      False, "Choose the seed before you promise the bank anything, and choose it from evidence: work with the adults to list kinds whose references honestly state a cold requirement — many native flowers and perennials carry one — and copy each kind's stated weeks onto its card word for word, because the bank's whole discipline is that the cold period comes from the seed's own instructions, never from a crew member's confidence. Reject any kind whose reference is vague about the cold it needs; a bank built on guesses is a fridge full of jars. Prepare the cold beds in advance — sand or vermiculite dampened, wrung, and checked by hand — and agree the vault shelf in writing with whoever owns the fridge or the cold frame: the shelf is booked for the longest term on the list plus the test weeks, and a card on the shelf edge says what the jars are and when they may be touched, which is at the rounds and at no other time. Set the bank book's first pages up now: the intake table, the weekly round page, and the spring test's empty verdict columns, so the bank is a record from the first jar, not a memory reconstructed in spring.",
      ["Intake day, the framing said at the table of seed packets and empty jars: 'Cold is an ingredient, and the calendar is the recipe. Some seeds will not grow, however warm and kind the spring, until winter has passed through them — the cold is not storage, it is instruction, and these kinds are waiting for it the way a letter waits for its address to be finished. This bank gives them that winter properly: each kind in its own jar, in damp sand, labelled with its name, its source and the exact weeks its own reference demands, and entered in the book before it goes cold. Then we wait, and waiting is the work. The bank is checked weekly, briefly, by the rota — damp checked by eye, any jar that has dried re-damped by the spoonful, any jar that smells wrong reported the same day — and no jar is opened early to see how it is getting on, because a seed mid-winter cannot report, and opening the jar only warms the winter we are supposed to be keeping.' Jars are filled, labelled and entered one kind at a time, each entry read back aloud by a second crew member before the jar joins the vault — the bank's first law is that a jar and its book entry are the same fact in two places.",
       "The weekly round, run by the rota pair whose names head that week's page: the vault is opened once, the jars are read in book order, and each jar's state is entered in the round's plain categories — damp right, dried at the surface, too wet, suspect — with remedies applied by the book's rules and no others: a dried surface gets a spoonful of water worked in gently; a jar standing wet gets its lid rested ajar for that week only, and the book says so; a suspect jar — mould spreading beyond a spot, a smell that was not there last week — is lifted out, shown to the adult the same day, and its fate (clean seed moved to a fresh bed, or the batch honestly written off) is entered with the reason. Chill weeks are tallied per jar on the round page, counted from the intake date, so the book always knows how much winter each kind has actually had — a jar that spent a week out of the cold during a fridge failure has that week struck from its tally in the open, because the bank counts the winter the seed received, not the winter the calendar claims.",
       "Due-out day, when a kind's tally reaches its stated weeks: the jar comes out of the vault at the round, its entry is closed with the date and the true chill tally, and the seed moves to the test — a counted sample, never the whole batch: twenty seeds where the batch allows, laid on damp paper in a labelled tray, kept at the room's ordinary warmth, and watched. The rest of the batch is sown as the kind's reference directs — in trays, in pots, or in the ground at its season — by the crew, with the sowing entered in the book beside the intake entry, so every jar's story can be read entire: in on a date, cold for so many honest weeks, out, sown, tested. A kind whose reference asks for warmth-then-cold or a second winter is not argued with at the table; the book takes the reference's side, the jar's new card is written from the reference again, and the bank's patience is extended in writing, which is what banks are for.",
       "The spring test, the bank's examination: the counted trays are read on the book's stated days — first check at the reference's earliest honest date, then weekly — and germination is counted as it is defined on the intake card: a root out, not a swelling, not a hope. The count is entered as a number out of the number laid down, in the same ink whether it delights or disappoints, and the verdict page is written per kind: the percentage the test actually grew, the chill tally it grew from, and the bank's one earned sentence about that kind ('eleven weeks was enough; nine was not tried and will not be claimed'). Batches that fail entire are not hidden or quietly composted — the failure is entered, the likeliest cause is named from the book's own evidence (a dried week, a suspect jar forgiven too long, a reference followed at second hand), and the kind is either re-banked next winter with the correction written on its new card, or struck from the bank's list with its reason, in the open.",
       "Closing the bank's year, the shelf and the book handed on: the vault shelf is emptied, washed and released with thanks to its owner; the sown trays and pots are labelled from the book and handed to whoever will grow them on, with their kind's page copied for the grower; and the crew writes the bank's closing page together — kinds banked, kinds proved, the test's best and worst numbers side by side, and the one instruction next winter's bankers will need most, earned at the fridge door. The tell-back is said over the closed book: 'This bank took seeds that were waiting for winter and kept that winter honestly — labelled, logged, checked weekly, and counted by the weeks the seed actually received. Spring graded us, in numbers, tray by tray, and the book holds the grades we liked and the grades we did not in the same handwriting. Cold is an ingredient. We measured it like one.' The book is stored with the empty jars and the marker where next winter's crew will find the whole bank together."],
      "A single-kind version (a first bank or a short winter): one kind, banked entire by the full discipline — intake, weekly rounds, due-out, a counted test — because one kind banked honestly teaches the whole bank.",
      "A cold-frame version (no fridge shelf to be had): the jars winter outdoors in a cold frame or a buried, shaded box, the rounds read a thermometer beside the jars, and the chill tally is counted in weeks the frame actually stayed cold — the book's honesty matters more outdoors, not less.",
      safety="Seed is treated as what it is — a material, never a food: nothing from the bank is tasted by anyone, jars and trays are labelled BANK, NOT FOOD on the vault shelf itself, and hands are washed after every round before eating, because seed may arrive dressed or dusty from its supplier and the bank does not ask which. Only kinds from trusted suppliers or known, identified garden stock are banked — no seed is gathered from plants nobody can name, and any kind whose reference mentions toxicity is banked, if at all, in a jar marked with that fact in the adult's handwriting and handled by the rota with gloves. Damp sand and vermiculite are worked dry-handed or gloved, never blown clear and never shaken into the air of a small room; a spilled jar is swept, not breathed. The fridge rule is absolute and hygienic: bank jars live only on their agreed shelf, sealed, away from food they could touch, and a jar that has been in the bank never returns to kitchen service afterwards. Broken glass in the vault is the adult's clean-up, reported the day it is found, with the jar's seed written off in the book rather than picked through by the crew.",
      tags=WINTER_SPRING, copy_free=True, no_elimination=True,
      inclusion="The bank's work is table work and book work by design, and its authority sits exactly there: the rota's reader calls each jar's state aloud while the keeper enters it, and the keeper's chair — seated, at the vault or the table, with the book, the cards and the tally — is the bank's memory and conscience, a full office held at whatever pace the keeper works. Labelling welcomes every hand: labels can be written, dictated to a scribe verbatim, or lettered from the bank's stamp set where the site keeps one, and the read-back law means no jar's truth depends on one person's handwriting or eyes. The weekly round is short, scheduled, and published a season ahead with named understudies, so no member's winter depends on never being ill, and a round missed is a round the understudy runs from the book — the book, not any person's memory, is what the next round reads. The spring test's counting can be done from photographs the rota takes of each tray, checked at the table by counters who never stood at the vault, and their counts carry the same ink: the bank grades seeds, and it does not grade its bankers.")]
PACK += [
    # ---------------- Outdoor, just teens (outdoor age-13/14 primary 6 -> 7) ----------------
    A("transect-line-field-survey", "Transect Line Field Survey",
      "Teens survey one fixed line across real ground — quadrats at set intervals, every plant and surface recorded square by square, season after season.",
      ["outdoor"], (13, 14), (4, 16), (45, 60), ["outdoor"],
      ["a transect line that can stay honest (a long tape or a marked rope of fixed length, with its two end points fixed by landmarks the crew can find again in any season — a gate post, a path corner, a named tree — because a line that wanders is a new survey every round)", "quadrat frames, one per survey pair (a square frame of a stated size, made or borrowed — every pair's square the same size, because counts from different-sized squares cannot be compared and the survey lives on comparison)", "the survey sheets and the line book (one sheet per round: date, weather, last rain, and a row per quadrat — what grows, what covers, what the surface is — kept in a hardback book that is the line's whole memory)", "the site guides (a trusted flora and field guide from the site's shelf, used at the square, in the hand of the pair working it — names are given only as far as the guide honestly carries them)"],
      False, "Walk the ground before the line is promised, and choose the line the way a surveyor chooses it: it should cross a real change — path edge to open grass, sun to shade, dry to damp — because a line across sameness will record the same square ten times and teach the crew that surveying is copying. Fix the two ends by landmarks a stranger could find from the book's description alone, photograph or sketch the line's run for the book's first page, and agree with whoever owns or manages the ground that the line may be re-walked across the seasons — the survey's whole value is return, so the permission is for the year, not the afternoon. Set the quadrat intervals now and write them on the book's first page as law: the same number of squares, at the same measured intervals, at the same frame size, every round, whatever the ground is doing that day. Check the guides against the ground on your own walk — note the handful of kinds the crew will meet constantly, so the framing can name them honestly as the line's regular citizens.",
      ["The framing, at the line's near end, tape still rolled: 'The line does not move; that is what makes it evidence. Today we lay one line across this ground and we read it square by square — not the prettiest square, not the interesting corner, the squares the intervals give us, in order, whether each one thrills us or bores us. A survey that only records what catches the eye is a walk with a notebook. Ours records what is actually there: every kind we can name, named only as far as the guide carries us; every kind we cannot name, described so honestly that next round's crew can tell whether it is the same stranger again. Cover is estimated square by square and argued out loud between the pair before it is written, because two estimates averaged in the open are worth ten written in silence. When this line is re-walked in another season, the book will be able to say what changed — and it will only be able to say it if today's squares were read at the same intervals, in the same way, with the same honesty about the dull ones.' The line is laid, the ends are checked against the book's landmarks, and the first quadrat is placed by measurement, not by eye.",
       "The survey round, worked square by square in the line's own order: each pair takes its quadrat at its interval, sets the frame flat without flattening what grows inside it, and reads the square in the sheet's fixed order — surface first (bare earth, leaf litter, stone, path, water), then cover by kind, estimated in quarters and argued aloud as the framing promised, then the citizens: every plant kind present, named from the guide or described as a stranger ('narrow, glossy, three leaves, no flower, square four'), and any animal evidence entered as evidence — a feather, a burrow mouth at the frame's edge, a web — never inflated into a sighting. The sheet's rule for names is the survey's honour: a name the pair cannot support from the guide is written as a description, because a wrong name in the book will be believed by strangers, and a good description will be recognised by them. Pairs call their finished square to the book-keeper, who reads the entry back before the frame moves — a square is not surveyed until the book holds it.",
       "The comparison round, at the table or the line's end, while the ground is still in view: the new sheet is read against the line's last round, square by square, and the differences are entered in the book's comparison page in the survey's plain shapes — arrived, vanished, spread, thinned, unchanged — with the season and the weather entered beside them, because a difference without its season is a riddle the book sets its own readers. The crew names its surprises honestly and its non-surprises with equal respect: a square that has not changed in a year of rounds is a finding, and the book says so, because stability is information a one-off visit can never give. Any square the pairs argued over longest is marked for the next round's first check — the survey's way of admitting where its own eyes are weakest — and unknowns that have now appeared in three rounds running are taken to the guides a second time, together, with the book's descriptions as the evidence.",
       "The disturbance law, taught before the first boot crosses the line and kept every round: the crew works from the line's side, never walks the squares it is about to read, and replaces anything it lifts — a stone turned for the reading goes back turned-side down as it lay, because the survey visits the ground, it does not rearrange it. Anything the crew cannot read without damaging — a nest at a quadrat's heart, a patch too fragile to frame — is entered as present-but-unread, with the reason, and that entry counts as a completed square: the survey's respect for its ground outranks its appetite for a full sheet, and the book says so in the round's notes where the next crew will learn the law from the record as well as the framing.",
       "Closing the round, the line is rolled and the book is finished at the ground: the crew walks the line once at a stranger's pace, checking the ends' landmarks against the book's description and correcting the description if the ground has changed it — a fallen branch, a moved fence — because the next crew finds the line by those words. The round's closing page is written together: squares read, kinds named, strangers described, the comparison's headline changes, and the one square the crew would show a visitor to explain what a transect is. The tell-back is said standing on the line's ground: 'This line was here before us and it will be walked after us, by crews reading the same squares at the same intervals, and the book will keep what we all found in the same order. We did not pick the pretty corners. We read what the intervals gave us, we named only what we could prove, and we left the ground as it lay. That is a survey: the line does not move, and neither does the truth about it.' The tape, frames and book are stored together where the next round — this crew's or another's — will find the whole survey in one place."],
      "A one-square version (a first crew or a tiny ground): a single quadrat read entire, argued entire, and entered entire — the whole discipline at one square's scale, with the book opened and the laws stated, ready to grow a line next round.",
      "A two-line version (a confident second-season crew): a second line laid at right angles across the first's most changeable stretch, read on the same day by the same crew, with the crossing square read twice and the two readings compared in the book.",
      safety="The ground sets this record's laws and they are read at the line's end before the tape unrolls: the crew works the ground the adults have walked and approved for that day — a line is re-walked only when its ground is in an ordinary state, and flood, ice, nests in season, or any works on the ground postpone the round, with the postponement entered in the book as a finding, not a failure. Nobody leaves the line's ground alone; pairs stay within call of the book-keeper, and the route in and out is the route walked at setup, over the firmest ground the site offers. Plants are read, never tasted — a kind the guide names as harmful is entered from a full step away, and hands that have worked squares of unknown kinds are washed before food, without exception. Anything sharp the ground surrenders — glass, wire, a lost blade — is lifted by the adult's gloved hand into the sharps tin the adult carries, never a crew member's pocket, and the square's entry notes the find. Tools are only tape, frames and books; the survey carries nothing that cuts, and that is deliberate.",
      copy_free=True, no_elimination=True,
      inclusion="A survey divides its authority as fairly as its line divides the ground: the book-keeper — seated at the line's end or at the table the ground allows, with the sheets, the guides and the comparison pages — holds the survey's memory and reads every entry back, which makes the keeper's the casting voice on what the book holds. Quadrat pairs share the reading by strength and reach as they agree it: one frames and steadies, one reads and names, and the arguing of cover — the survey's intellectual heart — is talk, open to every member of the pair at full standing. Squares can be read from photographs a pair takes square-on at the frame, identified and estimated at the table by readers whose ground is the book rather than the field; their estimates carry the same ink, argued the same way. The route to the line is chosen at setup for the firmest, most step-free approach the site offers, the round's length is set by the slowest pair's honest pace and stated in advance, and the rota of rounds is published by season — the line does not move, and nobody is surprised by it."),

    # ---------------- PE & movement, just teens (pe-movement age-13/14 primary 6 -> 7) ----------------
    A("long-rope-turning-crew", "Long Rope Turning Crew",
      "Two turners, one long rope, a whole crew jumping in turn: turning is the skilled job, entries are timed to a moving rope, and nobody jumps alone.",
      ["pe-movement"], (13, 14), (6, 24), (30, 50), ["indoor", "outdoor"],
      ["one long rope of honest length and weight (long enough for two turners standing well apart and three jumpers between them, heavy enough to keep a true arc — a clothesline-weight rope turns kindly; a flyaway cord teaches nobody timing)", "a flat, clear turning ground agreed in advance (the crew's floor: no obstacles inside the rope's whole sweep plus a body's length on every side, checked by walking the sweep before the rope first turns)", "the crew slate and chalk or marker (the session's record: who turned, who entered clean, which figures the crew landed — kept by the crew's own keeper at the rope's side)", "a second, shorter rope for the practice corner (where entries are rehearsed at walking pace against a rope turned by hand, slowly, before any jumper meets the long rope at full turn)"],
      False, "Choose the ground before you choose the figures, and choose it like turners: the rope's sweep is the session's true size — walk the full arc the rope will travel, plus a falling body's length beyond it on every side, and clear or rule out everything inside that country. Test the rope yourself: turn it with another adult or an experienced teen and feel its arc — a rope that will not hold a steady, even rhythm at a kind height is replaced now, not cursed later, because every jumper in the session will be asked to trust this rope's timing with their feet. Set the session's shape in advance and write it on the slate: turning practice first, entries second, figures last, because a crew that starts with tricks has skipped the two skills the tricks stand on. Pair the first turners deliberately — your steadiest pair, not your loudest volunteers — since the whole room will calibrate its courage on the first rope they are offered, and a kind first rope makes brave jumpers of the cautious.",
      ["The framing, rope at rest across the ground: 'The rope belongs to the turners; the jumping belongs to everyone. In this crew the skilled job is not the jumping — it is the turning. Turners hold the height, keep the beat, read the jumper, and rescue a failing entry by lifting the rope over it instead of letting it trip: a good turner makes ordinary people look brave. Jumpers: your job is timing, and timing is learnable — you watch the rope, you enter on its far beat, you jump in the middle where the rope is honest, and you leave the way you came in while the rope is still turning. Nobody jumps alone today, nobody is counted out, and a miss is information, not a verdict: the slate records what the crew landed, and a jumper who misses twice changes jobs — to turning, to keeping, to the practice corner — and comes back when they choose, because a crew has many jobs and all of them are the session. We start with the rope turning empty, until its beat is in the room's feet. Then we jump.' The rope turns empty for a full minute while the crew claps its beat, so the first entry is made into a rhythm the whole room already holds.",
       "Turning school, the session's foundation, run before any entry at speed: pairs turn for one jumper-free minute each while the crew reads their rope aloud against the slate's three laws — height (the arc's top stays where it was promised, neither climbing to show off nor sagging to rest), beat (one turn, one beat, no hurrying a jumper by speeding and no rescuing by stopping), and hands (handles turning from the wrist, elbows quiet, the turners' eyes on the middle of the rope, never on their own hands). A pair whose rope drifts is coached by the crew in the open — turning is taught publicly because it is practised publicly — and every crew member turns before anyone is allowed to specialise in jumping, because a jumper who has never turned does not yet know what they are asking of the rope. The practice corner runs alongside for entries at walking pace: rope turned slow and low by hand, jumpers stepping in, standing the middle for three turns, and stepping out, until the geometry of entry is in their feet rather than their worries.",
       "Entries, the session's heart, built one jumper at a time: the crew forms its line at the rope's open side, the turners call the beat aloud until the room holds it, and each jumper enters on the far beat — in as the rope passes away, two settling jumps in the middle, out on the turners' call while the rope still turns. Turners rescue as the framing promised: a jumper arriving late is lifted over by the rope's height, a jumper tiring mid-entry is talked out on the beat — 'out on three' — never left to tangle and fall in front of the line. The slate records clean entries by name and rescues by name too, in the same chalk, because a rescued entry is a turner's achievement recorded at the jumper's line, and the crew reads both columns with the same pride at the close. Jumpers who want more take the harder doors the session offers in order: entering from the far side, turning a half-turn mid-entry, two jumpers entering on consecutive beats — each door named, demonstrated by its first taker, and never owed by anybody.",
       "Figures round, when the entries are steady and only then: the crew builds its figures from the skills the session has actually shown — jumpers in pairs entering together, a jumper crossing to exit the far side, three in the middle for a counted run of turns, the whole crew in for one heroic counted ten — each figure attempted by volunteers, spotted by the turners' rescue, and chalked on the slate landed or not-landed with the attempt's true number. A figure that fails three honest attempts is retired by the crew for the day, in the open, and its retirement is chalked like a landing, because knowing what today's crew cannot yet hold is a result the slate exists to carry. Between figures the rope rests and the turners rotate — turning is work, arms tire, and a tired turner's rope drops its height exactly when jumpers are bravest; the rotation is set by the slate before the round starts, so no pair turns a whole figures round on goodwill and fumes.",
       "Closing, the crew's count and the rope coiled by its turners: the slate is read aloud entire — turners by name, clean entries, rescues, figures landed and retired — and the session's one number is agreed and chalked large: the longest counted run the whole crew held in the middle together, whether it is forty turns or four, because that number, honestly counted, is the crew's mark to beat next session and nobody else's business. The tell-back is said with the rope coiled on the ground between the crew: 'A long rope is a promise two people keep with their wrists so that other people can be brave in the middle of it. Today the turners held the height, the jumpers trusted the beat, and every miss taught the crew something the slate now holds. Nobody jumped alone, nobody sat out a failure, and the rope never stopped being kind on purpose. Next session the mark on the slate is waiting. Crews are beaten by it or beat it — either way, it will be counted honestly.' The rope is inspected as it is coiled — fraying noted to the adults — and stored where the crew will find it with the slate."],
      "A two-turner, one-jumper version (a small crew or a first session): the whole discipline at its smallest size — turning school, practice corner, entries, the slate — with figures saved for the session the entries hold steady.",
      "A double-rope version (a crew whose single rope is truly steady): two ropes turned egg-beater style by four turners, entries rehearsed first against one rope turning, and the session's laws — rescue, rotation, honest counting — applied double, because the difficulty is.",
      safety="The rope's sweep is this record's first law and it is geographic: nobody stands, sits, crosses or leaves belongings inside the turning arc plus a body's length beyond it, except the jumpers whose entry the turners are expecting, and the line waits outside the sweep at the open side where the framing placed it. Turners hold handles with a grip that keeps the rope if it snags — never wrapped around a hand or wrist, because a snagged rope must be droppable, and a rope that catches a jumper is dropped by both turners on the adult's call or the turners' own judgement, instantly, without finishing the beat. Jumpers wear shoes that grip and stay on; loose laces are tied before the line, not during an entry. The practice corner is not optional for new jumpers and re-entry after a tangle is always through it — nobody returns to the long rope shaken and unbriefed, because the next entry after a fright is the session's most losable moment. The adult watches turners for the fatigue signs the rotation exists to prevent — dropping height, drifting beat — and ends or rests the rope on those signs as readily as on any fall; a fall inside the rope stops the session until the jumper is up, checked, and choosing for themselves whether the practice corner, another job, or the line is next.",
      copy_free=True, no_elimination=True,
      inclusion="Turning a long rope is a seated-tolerant, strength-sharing craft, and this crew staffs it as the honour it is: turners may turn sitting on a low bench at the rope's end where the ground allows, handles can be worked by a pair sharing one end in relay, and the slate-keeper — caller of the beat, recorder of entries and rescues, holder of the crew's mark — runs the session's voice from the rope's side at full authority. The beat is given in sight as well as sound: the lead turner raises a free shoulder on each turn for jumpers who read rhythm with their eyes, and entries are called by gesture as well as voice as the crew agrees at the framing, so no jumper's timing depends on hearing one voice across a turning rope. The practice corner runs at whatever pace its jumper sets, for as many rehearsals as they want, with no audience but its turner — a door into the session that never has to be explained to the line. Every job in the crew rotates through the slate's published order, so a member whose day is turning, keeping and coaching entries is not having a lesser session: the framing said the skilled job is the turning, and the crew's honours are chalked to prove it."),

    # ---------------- Music & rhythm, just teens (music-rhythm age-13/14 primary 6 -> 7) ----------------
    A("part-singing-choir-first-rehearsals", "Part-Singing Choir, First Rehearsals",
      "Teens form a choir that sings in parts: sections, blending, a conductor's beat shared in rotation — two lines held at once, by listening.",
      ["music-rhythm"], (13, 14), (8, 30), (45, 60), ["indoor"],
      ["one song the whole room can honestly sing, chosen before the first rehearsal (short, with a melody that divides into two singable lines — a round, a harmonised folk chorus, or a two-part arrangement the adult can teach by ear; the choir's first song is a vehicle, not a monument)", "the words and the two lines, taught by ear and held on the room's board (the choir learns by listening and repeating, line by line — nobody's place in the choir depends on reading notation, and the board carries the words for every singer alike)", "a pitch to start from, given by an instrument or a confident voice (every rehearsal begins from the same given note, found the same way, so the choir's ear is trained on a ritual it can rely on)", "the rehearsal log (one page per session: what was sung, which joins held, which fell, and who conducted — the choir's memory, kept at the piano or the board by the session's keeper)"],
      False, "Choose the first song the way choirs actually survive their first month: short enough to learn entire in two rehearsals, sturdy enough to bear repetition, and built so its second line is a real line — singable alone, interesting alone — because a part that is only a shadow of the melody teaches its singers that they are the lesser half, and they will sing like it. Learn both lines yourself, entire, by ear, before the first rehearsal: the conductor who must stop to remember a part teaches the choir to stop with them. Set the room before the singers arrive — chairs or standing marks in a shallow arc, sections left and right with the join where the conductor stands, the board carrying the words in large clear lettering, and the starting pitch's source placed and tested. Fix the rehearsal's shape now and keep it all term: warm-up, lines apart, lines together, one full run, the log — a choir settles into its shape the way a crew settles into a rota, and the shape is what carries a tired rehearsal when enthusiasm is doing other work.",
      ["The framing, singers standing in the arc, before a note is sung: 'Blending is listening louder than you sing. A choir is not a crowd singing the same line louder — it is a room holding two lines at once, and the holding is done with ears, not throats. Your section's line is yours to keep; the other section's line is yours to hear. When both are true at once, the chord happens, and no single singer made it — that is the whole art, and it is learnable by everybody in this arc, because it is made of listening, and listening can be practised. We will learn each line apart until it is boring, and boring is the doorway: only a line you can sing without thinking leaves your ears free to hear the other one. Nobody sings a solo in this choir's first term, nobody is auditioned, and a singer who loses their line does the choir's own rescue — drops to a hum, finds the line's next landmark, and climbs back in. The log will record what held and what fell, honestly, because next rehearsal starts from the truth of this one.' The starting pitch is given, the warm-up runs its short, unglamorous course — breath, hums, the scale sung as one body — and the first line is taught to the whole room together, before any sections divide.",
       "Lines apart, the rehearsal's patient middle: each section learns its line with the conductor while the other section does the choir's second job — listening entire, following the words on the board, and marking with a raised hand the exact bar where the sung line surprised them, because a section that has truly listened to the other line will join it twice as surely when the parts meet. Lines are built in short reaches — two bars sung, sung again, sung from memory with the board's words covered by the conductor's hand — and a reach is not left until the section can start it from the given pitch without being sung to, since a choir that needs to be carried into every reach cannot yet carry itself into a chord. Section leaders emerge here and are named by the conductor on evidence — the singer others are already listening to — and leadership in this choir means being findable: a steady voice at a section's heart that quieter singers can lean an ear on, never a louder voice showing the section its place.",
       "Lines together, the moment the choir exists: the sections face each other across the conductor, the pitch is given, and the song runs at walking pace, both lines at low volume — the conductor's standing instruction is half as loud as feels right, because a chord balanced quietly can be heard by its own singers, and a chord shouted is two sections competing in the same weather. When the join falls — and the log expects it to fall, early and often — the rehearsal stops at the fall, not after it: the conductor names the bar, each section sings its line alone across that bar once, and the join is retried at the same walking pace, because a join mended slowly in rehearsal is a join that will hold at speed in performance. Singers who lose their line run the framing's rescue in the open — hum, landmark, climb back — and the conductor praises rescues by name in the log, because a choir that honours recovery over perfection will recover in public, where it counts, instead of dissolving.",
       "Conducting rotation, the choir's second craft: once the song holds at walking pace, the beat passes around the arc — each singer who wants it conducts one full run, with the choir's laws stated before their run begins: the beat is given in the hands, plainly, at a size the back row can read; the start and the stop are the conductor's two ceremonies, rehearsed before the run; and a conductor who loses the choir stops it with both hands raised, without apology, because stopping cleanly is conducting too. The choir sings for its amateur conductors at its kindest — following the beat that is given, not the beat that is expected — and the log records each conductor's run with the choir's honest note: where the beat was clearest, where it wandered, and what the next run should keep. A singer who never conducts loses nothing; the rotation is an offer renewed each rehearsal, not a toll the song charges.",
       "Closing the rehearsal, one full run at the song's true pace, sung standing as a performance for the room itself, and then the log is written while the chord is still in the singers' ears: the keeper enters the session's joins held and fallen with their bars, the conductors by name, and the choir's one sentence to its next rehearsal — the reach to rebuild, the join to trust — agreed aloud by the whole arc. The tell-back is said in the arc, singers still standing in their sections: 'An hour ago this song was two lines in two halves of a room, and both halves could lose them. Now the lines hold together at walking pace and better, held by listening, rescued without shame, and written down true — the falls in the same ink as the joins. That is a choir: not the loudest room, the listeningest one. Next rehearsal starts from the log, not from hope.' The board is left carrying the words for the next session, the log is stored with the song's card, and the arc is straightened by the sections who stood in it."],
      "A round-only version (a first choir or a single session): the whole choir learns one sturdy round entire and sings it in two, then three entries — part-singing's whole discipline, holding a line against itself, inside one song everybody already half-knows.",
      "A performance version (a choir with a term's log behind it): the song is sung for a real small audience — another class, a family evening — with the choir's laws intact: no solos added for the occasion, the conductor drawn from the rotation, and the log's entry for the performance written by the singers, not the audience.",
      safety="Voices are the instruments here and they are worked like instruments: the warm-up is never skipped to save time for the song, singing stays at the volume the framing set — a rehearsal that has to shout over itself is stopped and reset quieter, by the conductor, as a craft correction and a kindness — and any singer whose voice is sore, cracking with illness, or simply unwilling that day hums, mouths, or keeps the log, at full standing, because a choir that benches its hoarse has misunderstood both music and membership. Rehearsals are seated-and-standing in turns by design, with water in the room and a singer's right to sit for any run stated at the framing, so breath and stamina are managed by the shape of the session rather than by individual endurance. The room's volume is the adult's care as much as the choir's: sessions are held where an hour of full singing will not be visited on a neighbouring room's examinations, and the door arrangement is settled before the first rehearsal, not negotiated after the first complaint. Nothing in this record involves food, flame, tools or travel; its hazards are tired voices and bruised pride, and both are governed by the laws above.",
      copy_free=True, no_elimination=True,
      inclusion="A choir built on listening has more doors in it than most rooms: the log-keeper's chair — joins, conductors, the sentence to next rehearsal — is seated work at the choir's centre, and the keeper's ear is the session's record of what actually held. Singers join at the volume and in the register their voice honestly has: lines are taught by ear in short reaches, words stand large on the board for every singer, and a singer may hum a line entire for a whole term and be, in the log's words, a pillar of their section, because blend is built from steadiness, not display. The conducting rotation is offered in whatever size of gesture a conductor commands — a full beat, a raised hand for starts and stops, a counted nod agreed with the choir in advance — and the choir follows the beat it agreed to read. Sections are arranged so every singer stands or sits beside a steady voice; the arc is set step-free with chairs woven into it as ordinary furniture, not exceptions, and a singer's place in the arc is assigned for hearing and company, never for appearance. Nobody auditions, nobody is solo'd without asking, and the log records rescues with the same honour as clean runs — the choir's way of keeping its doors as wide in fact as in the framing.")]

PACK += [
    # ---------------- Rainy day, just teens (rainy-day age-13/14 primary 6 -> 7) ----------------
    A("foley-radio-play-recording", "Foley Radio Play, Recorded Live",
      "A scripted radio drama performed entire on a rainy day: actors at the microphone, live sound effects made by hand at the Foley table, one take per scene.",
      ["rainy-day"], (13, 14), (6, 24), (50, 60), ["indoor"],
      ["a short play the room can perform entire (an original script written by the group in an earlier session, or a classic short drama the adult has chosen and read entire in advance — fifteen minutes of playing time is the honest size; every part cast, every scene's effects listed on its cue sheet)", "the Foley table (the studio's instrument bench: gravel tray for footsteps, coconut shells or cups for hooves, a sheet of metal or a baking tray for thunder, water basin and jug, keys, doors in miniature — a hinged board with a latch — celery or lettuce for the sounds nobody asks about twice; every effect tested for its sound before the session)", "one recorder at the room's centre, adult-run (a phone or recorder on a stand, set before the cast arrives — the studio's only machine, and its operator's whole job; levels checked on a rehearsal line, never during a take)", "cue sheets and the studio log (one sheet per scene: who speaks, who effects, in what order — and the log where takes, retakes and their reasons are entered, scene by scene, by the studio's keeper)"],
      False, "Read the whole play aloud yourself before the session, with a pencil, and mark it like a studio manager: every line's speaker, every effect the script implies, and every place the audience will need a sound the words cannot give them — a door, weather, a journey. Build the Foley table from that marked script and no other list, and test every effect at the volume the recorder will hear: an effect that sounds magnificent across a room may arrive at the microphone as a thud, and the table is tuned at rehearsal distance, not performance distance. Cast on the session's own evidence as the framing will promise — voices tried in the warm-up, parts given where they sit well, and the play's small parts cast with the same ceremony as its leads, because a radio play has no small sounds. Set the studio before the cast enters: microphone at the centre with its distances taped on the floor — near mark for whispers, far mark for shouting rooms — actors' chairs in an arc the director can see entire, the Foley table within the director's sightline and out of the actors' way, and the rain outside, which booked the session, acknowledged as the studio's first effect and the only one nobody has to make.",
      ["The framing, cast in their arc, Foley table laid like an instrument: 'The audience believes its ears; the studio's job is to deserve that. A radio play has no faces, no costumes, no weather but what we make — every listener will build the whole world from our voices and the sounds this table honestly produces. So the studio's laws are a listener's laws: an effect is made at the moment it happens in the story, never early to get it over with and never late as an apology; an actor who dries does not stop the scene — the director's raised hand holds the room, the prompter gives the line's first words, and the take rolls on, because a pause can be believed and a panic cannot. We record scene by scene, one full take and at most one retake, and the retake is granted for a reason the log can state — a missed cue, a dried scene, the rain drumming through the best line — never for a vague wish to be better, because a studio that chases perfect takes will still be chasing when the bell goes. What we keep is what a listener will believe. That is the standard, and it is high enough.' The cast warms its voices on the play's own first lines, each actor finding their distance from the microphone, and the Foley crew runs the table's roll-call — every effect named and sounded once, in cue order, for the director's ear.",
       "Scene takes, the studio at work: the director calls the scene, the keeper reads its cue sheet aloud — speakers, effects, order — the recorder's operator shows the running hand, and the take begins on the director's single word. Actors play to the microphone's marks, near for the confidences, far for the doorways, and the Foley crew makes the scene's world at the exact beats the script has set them: footsteps that walk at the actor's own pace and stop when the actor stops, a door that opens when the line says it opens, weather that starts under the line that names it and no sooner. The director watches the cue sheet, not the performers — a director watching faces misses cues — and holds the room through trouble with the framing's raised hand, giving a dried actor to the prompter and a missed effect its second chance at the scene's next natural beat, because a take is a living thing and the studio's skill is keeping it alive, not stopping it dead at every flaw.",
       "The retake law, applied in the open at each scene's end: the director states the take's verdict first — keep, or retake and why — in one sentence the keeper can write, and the cast hears the reasoning before they hear the verdict's effect on their work. A retake reruns the whole scene, never a patched line, because radio time is continuous and a spliced performance sounds like what it is; the second take is the scene's last, whatever it holds, and the keeper enters both takes' fates in the log with their reasons side by side. Between scenes the studio resets in its drilled order — Foley table checked against the next cue sheet, actors reseated, distances re-taped where feet have wandered — while the keeper reads the log back to the room, so the company always knows what it holds: so many scenes banked, so many to go, and the rain, if it is still performing outside, credited in the log as an uncredited guest.",
       "The playback, the studio hearing itself as its audience will: when the last scene is banked, the room changes shape — chairs turned, the recorder at the front, the company seated as listeners, in silence, for the whole play played entire without a pause for pride or apology. Listening is the cast's final craft and it is taught as plainly as the rest: attend to what a stranger would believe — could you follow who was where? Did the door sound like a door? Where did your own attention wander, and what was the play doing at exactly that moment? The keeper takes the company's notes at the playback's end, one per member, spoken or written, and enters them on the log's listening page without editing their disagreements, because a company that argues honestly about what its audience will believe is a studio learning its trade.",
       "Closing the studio, the play is named and filed: its title, cast, Foley crew, director and date are read into the recorder as the play's own opening credit, in the company's best ceremonial voice, and the log's closing page is written together — takes kept, retakes spent and their reasons, the effect the table was proudest of, the scene the playback proved. The tell-back is said with the Foley table still laid, before it is packed: 'This morning this was a script, a table of gravel and shells, and a room the rain had kept indoors. It is a play now, because actors held their marks, effects arrived at their moments, a director held the room without stopping it, and the log can show every decision we made and why. A listener who was never in this room will believe a world we built out of voices and honest noise. That is the studio's whole magic, and it is a trade, and today we practised it entire.' The Foley table is packed by its crew, every item checked against the cue sheets it served, and the play's file and log are stored together where the next rainy day will find a studio ready to reopen."],
      "A one-scene version (a single wet lunchtime): one short scene with three effects, cast, cued, taken twice at most and played back entire — the whole studio in miniature, laws intact, because the laws are the studio.",
      "A serial version (a term of rainy days): the company records one episode per wet session, the log carrying cast and cues between episodes, and the season is played entire at the term's end — a studio with a memory, and an audience of itself, growing pickier by the episode.",
      safety="The studio's hazards are ordinary room hazards made theatrical, and they are governed plainly: the Foley table's water lives in its basin on a tray, away from the recorder and its cables entirely — water and the studio's one machine never share a surface — and spills are mopped by the crew at the scene break, because a wet studio floor at microphone distances is a fall rehearsing itself. Cables run taped along the floor's edges, never across the actors' arc; distances are taped, chairs are set once and not drifted, and nobody crosses the studio during a take except at the director's signal, because a room performing blindness for its listeners must be able to trust its own floor. Effects are made with the table's listed items only — no glass is broken for any sound, ever, for any scene; the thunder sheet is lifted by its edges by two hands, gravel stays in its tray, and anything a script seems to demand beyond the table's honest means is re-imagined at rehearsal, which is the Foley's oldest professional pleasure. Volume is the adult's care: shouting marks are set at the floor's far tape for a reason, playback runs at a kind level, and a company that has spent an hour at performance effort takes its closing standing, stretching and talking quietly, because voices and ears both tire and the studio respects its instruments.",
      copy_free=True, no_elimination=True,
      inclusion="A radio studio is the most naturally open room in this whole archive, because its audience will never see it: casting is by voice and by wish, tried in the warm-up and settled where parts sit well, and a performer may act seated, standing, at the near mark or the far one, with their lines on a stand, in large print, or held by the prompter as a matter of the studio's ordinary furniture. The Foley table is a row of skilled, mostly seated crafts — footsteps in gravel can be worked by hands as surely as by feet, the thunder sheet is a two-person lift shared as agreed, and the table's chief, who cues every effect from the sheet, holds the studio's timing in their hands from a chair at its centre. Directing, prompting and log-keeping are full studio offices: the director's authority is voice and gesture, the prompter's feed is the take's lifeline, and the keeper's log is the company's memory — all three can be held by members who never step to the microphone, at the session's full standing. Cue sheets are read aloud before every scene as law, signals are given in sight as well as sound, and the playback is heard together with the company's notes taken spoken, written or dictated — a studio that believes its ears extends the same courtesy to its own."),

    # ---------------- Icebreakers, just teens (icebreakers age-13/14 primary 7 -> 8) ----------------
    A("partner-portrait-interviews", "Partner Portrait Interviews",
      "One deep interview per pair, notes kept, and then the introduction nobody else could give: you present the partner you actually met.",
      ["icebreakers"], (13, 14), (4, 30), (30, 45), ["indoor"],
      ["the portrait questions, three only, agreed and written large before pairs are drawn (the session's whole constitution: questions that ask for a life, not a label — the place that made you, the skill you would teach, the thing you are quietly proud of — screened by the adult against the framing's one rule)", "note cards and pencils, one card per interviewer (the portrait's evidence: notes taken in the partner's own words where they matter, because the introduction will quote them and a quotation must be earned)", "a way of drawing pairs that nobody games (names from a hat, drawn by the adult in the open — the session's fairness is its first impression, and a rigged draw teaches the room the opposite of the session's lesson)", "the portrait slate (the session's closing record: every pair, and beside each name the one line their partner's introduction was remembered by — kept by the session's keeper at the front)"],
      False, "Write the three questions before you write anything else, and test each one against the framing's rule — could a stranger answer this honestly to somebody they met ten minutes ago, and would the room be glad it heard the answer? Cut any question that fishes for confession, ranking, money, family trouble or romance; a portrait interview earns depth by the quality of its attention, not by the sensitivity of its material. Keep the count at three and resist a fourth: depth in this format is manufactured by time per question, and a fourth question taxes the first three. Decide the session's shape now — draw, interview, write, introduce — with minutes per stage stated, because the introduction round will expand to fill any vagueness the earlier stages leave it, and the writing stage is always the one a loud session tries to steal from. Prepare the hat draw entire and check your pairs arithmetic for the room's awkward numbers: an odd count makes one trio, interviewed as a triangle, and the plan for it is made now, at the desk, not discovered apologetically at the draw.",
      ["The framing, questions on the board, hat in the adult's hand: 'You introduce the person you actually met, not the one you expected. In the next half hour you will sit with one partner — drawn, not chosen, because chosen partners teach you about your friends and drawn partners teach you about people — and you will interview them under three questions only. Three questions is not a shortage; it is the discipline. You will have time to follow an answer where it goes — once, with one honest follow-up the questions allow: tell me more about that. Your card is for their words, not your summaries: when your partner says the exact sentence that is most them, it goes on the card in their words, inside invisible quotation marks you will treat as sacred when you stand up. Then you will introduce them to this room, and the room will judge your introduction by one standard only — did we meet the person you met? An introduction that performs the introducer has failed, however beautifully it is spoken. A plain one, with the true sentence in it, is the finest speaking this room does all year.' Pairs are drawn in the open, chairs are turned to face, and the room is given a full minute of settling before the first question is asked, because interviews begun in a scramble stay scrambled.",
       "The interview round, run in two halves so every partner is met both ways: the first interviewer asks, follows once where the answer invites it, and writes — and the session's writing law is stated before the round begins: notes are taken openly, on the card, where the partner can see them being taken, because a portrait sitting is a collaboration, not a surveillance; a partner may strike any line from the card by asking, at any moment, without giving a reason, and the line is struck in front of them. The adult calls the halfway turn by the clock the framing promised — interviews are not ended by energy but by agreement — and roles reverse entire: second interviewer, same three questions, same follow-up law, same card discipline. Pairs who finish early do not start a second, shallower interview; they sit with their cards and find the sentence, because the introduction they are about to give is made of the finding, and a pair still talking when the writing stage begins will give the room the talk instead of the portrait.",
       "The writing stage, ten honest minutes of quiet: each interviewer builds the introduction from the card alone, in the session's taught shape — the name, said first and said right (checked with the partner in a whisper before the round: pronunciation is respect, rehearsed, never improvised in public); the place that made them, in a line; the skill they would teach, in a line; the quiet pride, in their own quoted sentence where the card holds one; and the introducer's one closing line, the only place the introducer's own voice is licensed: what meeting this person added to the room. Introductions are written to be spoken inside a minute — the keeper holds the session's gentle clock, announced now so brevity is a shared discipline rather than a public correction — and a writer stuck for the closing line is given the session's loan of one: begin with the words 'we are luckier because', and let the card finish the sentence.",
       "The introduction round, the session's whole point, run as a ceremony of attention: pairs come forward together; the introducer speaks; the introduced stands beside them and is looked at by the room as a person met, not a specimen shown. The introduced partner holds one right, stated in the framing and honoured without debate: at the introduction's end they may add one sentence of correction or completion — 'all true, and also this' — which the keeper adds to the slate in their words, because a portrait's subject is its final editor. Applause is for the pair, both halves of it, and the keeper chalks the slate's line for each introduced name from the introduction's own best sentence, chosen by the room's murmur rather than the keeper's taste. Nobody is introduced by anyone they were not paired with, nobody's portrait is given in their absence, and a member who must leave before the round has their introduction given first, by agreement, or held unspoken — the session would rather keep one portrait back than give it to an empty chair.",
       "Closing, the slate read back and the cards given away: the keeper reads the slate's lines entire, name by name, the way a register is read — the room hearing itself as a gallery of met people — and then the cards change hands by the session's last law: your card about your partner is given to your partner, to keep, correct, or throw away as theirs, because the evidence of a portrait belongs to its subject once the introduction is spoken. The tell-back is said with the empty hat on the table: 'An hour ago this room was names and expectations. It is a gallery now: every person here was met by one pair of ears that was not free to wander, quoted in their own words, struck of anything they struck, and introduced by the only standard that matters — the person we met is the person you described. Drawn partners, three questions, one true sentence each. That is all a portrait has ever needed.' The slate's lines are copied into the session's record by the keeper, and the hat is stored with the question cards for the next room that needs meeting properly."],
      "A two-question version (a short session or a young-feeling room): the place and the skill, portraits at the same discipline in less time — the pride question is added at the session's second running, when the room has learned the laws.",
      "A return version (a group that has sat once): the same draw is kept, the questions deepen by agreement — the lesson learned the hard way, the person who taught you — and introductions are given from the new cards alone, with the first session's slate read at the close as the room's earlier gallery.",
      safety="This session's safety is the safety of being known, and its laws are stated in the framing because they are the framing: the questions are screened by the adult before the room sees them — nothing that fishes for confession, family trouble, money, romance, belief or difference — and any question that drifts there in a follow-up is the adult's to redirect, kindly and at once, because follow-ups are where screened questions go to become unscreened ones. The strike law is absolute and is the session's load-bearing rule: a partner may strike any line, any answer, any topic, at any moment, without a reason, and the striking is done visibly and without comment, by interviewer and room alike; an introduction that smuggles a struck line back in as a joke has broken the session's constitution and the adult ends that introduction there. Notes are open, cards are surrendered to their subjects at the close, and nothing from any interview is repeated outside the room by the session's members as gossip — what a portrait sitting hears is the room's, in the room, for the introduction. A member who would rather not sit is never argued with: the session always holds one full office — keeper of the slate — that participates entire without being interviewed or introduced, and taking it needs no explanation then or ever.",
      copy_free=True, no_elimination=True,
      inclusion="The portrait sitting is built so that attention, not performance, is its currency, and its offices reflect that: the keeper of the slate — the session's memory, its clock, its register-reader — is a full office held from the front, at the session's ceremonial centre. Interviews can be conducted in whatever register a pair shares: spoken, written question-and-answer on the cards themselves, signed, or through the session's ordinary patience with a partner's own pace and pauses — the three questions are the same, the follow-up law is the same, and a written interview's card is evidence of exactly the same weight. Note-taking welcomes every hand: notes may be written, dictated back to the partner for correction as they are made — some sitters prefer this, and the session treats it as a style, not a concession — or kept as the session's symbols and tallies where a card's keeper has agreed their key with their partner. Introductions may be read from the card, spoken from memory, or read by the keeper at the introducer's request, at identical honour: the standard is whether the room met the person, never how the meeting was voiced. Pairs are drawn by the hat for everyone alike, seating is turned chair-to-chair wherever the pair sits best, and the introduced partner's right of correction — the session's final editorial word — belongs to every subject without exception or assistance unless they ask for it."),

    # ---------------- Crafts, just teens (crafts age-13/14 primary 7 -> 8) ----------------
    A("one-sheet-zine-workshop", "One-Sheet Zine Workshop",
      "Eight pages from a single folded sheet: teens plan, sequence, letter and trade a finished zine — a whole publication with no editor but its maker.",
      ["crafts"], (13, 14), (2, 24), (40, 55), ["indoor"],
      ["one large sheet of plain paper per maker, plus spares for the folding casualties (the zine's whole body: a single sheet, folded and cut once, becomes eight pages — paper sturdy enough to take lettering on both sides without bleeding through is the one quality that matters)", "pens that letter honestly (fine markers or drawing pens, one dark ink per maker at least — a zine is read at hand's length, and its lettering is its typography, so the pens are chosen for the page size, not for decoration)", "the folding demonstrator (one sheet the adult folds, cuts and refolds in front of the room, slowly, twice — the fold is the zine's only machinery and it is taught until every maker can do it with their eyes on their own hands)", "the trade table and the workshop slate (finished zines are laid title-up for the trading round, and the slate records the workshop's titles and makers — the session's catalogue, kept by the workshop's keeper)"],
      False, "Fold the demonstrator yourself, entire, before the session, and then fold a second one badly on purpose — pages out of order, one page upside down — because the workshop's two classic failures are sequence and orientation, and you will teach both from evidence if you have the evidence in your bag. Plan the session's shape now: fold taught, pages planned on a thumbnail map, making in quiet, trading at the end, and defend the planning stage against the room's impatience in advance — a zine planned on its map can be lettered in one pass, while a zine improvised page by page discovers its own ending on page six and has nowhere honest to go. Choose the session's theme or its freedom and state it in the framing: a themed workshop (the zine of one true thing, the field guide to our corridor, eight pages about a sound) gives uncertain makers a floor to stand on; an open workshop trusts makers who arrive with pages already in their heads. Either way, the law that does not move is the zine's own: eight pages, one sheet, finished and traded.",
      ["The framing, one blank sheet on every table: 'Eight pages, one sheet, no editor but the maker. This sheet is a whole publication folded into a single skin: cover, six pages of inside, back cover — every copy handmade, every copy the original. Zines are the oldest do-it-yourself publishing there is, and their rules are a maker's rules: it must be finished, it must be readable at the distance a hand holds it, and its pages must arrive in the order its reader needs them — which is why we plan before we letter, on the map, where mistakes are free. Your zine answers to nobody's taste but its own; it answers entirely to its reader's comprehension. Lettering is typography. Sequence is plot. The back page is not where the sheet runs out — it is where the zine decides to end, and a zine that ends on purpose feels finished in a reader's hands in a way no extra page can fake. At the close we trade, title-up, every zine taken seriously by at least one reader who was not its maker. That is publishing: somebody else, reading.' The fold is then taught from the demonstrator, slowly, twice, the room folding along on practice sheets, until every table holds an eight-page blank that opens and turns correctly — the workshop's machinery, mastered before a word is written.",
       "The mapping stage, ten minutes that the framing has already defended: each maker unfolds their practice sheet flat and draws its ghost on the map card — eight numbered page boxes in the sheet's true arrangement, cover and back marked, the upside-down pages marked with the map's small arrow, because two of the inside pages live inverted on the flat sheet and every zine ever made has lost one maker's favourite page to that inversion. On the map, and only on the map, the zine is composed: cover title and image, the inside pages' beats in order — what opens, what builds, what the middle spread does, how the last inside page hands the reader to the back — and the back page's decision: a colophon with the maker's name and the zine's number, a final image, a message to the finder. Makers who compose fast help the table check maps, because map-checking is the workshop's peer craft: read another maker's plan as its reader will meet it, pages turning, and say whether the sequence lands. No lettering begins until its map has survived one other reader's eyes.",
       "The making, the workshop's long quiet: makers letter their real sheets from their maps, page by page in the sheet's flat order, turning the sheet as the map directs, and the room's laws are a print-shop's laws — pens down during another maker's question to the adult, because lettering spoiled by a jogged elbow is the workshop's one unforced error; spares are for true casualties only, claimed without shame and recorded by nobody, since a maker who ruins a sheet at page seven has learned the workshop's hardest lesson at the standard price; and the session's keeper keeps the slate of titles as covers are finished, reading each title aloud as it is entered, because hearing your zine named in the catalogue while your hands are still inky is the exact moment a worksheet becomes a publication. The adult circulates as the shop's master printer: asked for lettering help, sequence rulings, and the occasional steadying hand on a fold — never for content approval, which the framing has already abolished.",
       "The trading round, run as a bookshop, not a swap heap: finished zines are laid title-up on the trade table, makers stand behind the table as its booksellers for the round's first half — answering a browser's question about their zine in one sentence, the bookseller's discipline — and every maker takes at least two zines by other makers, chosen by their covers and titles, to read entire at the table. Reading is the trade's payment and it is made properly: a reader who finishes a zine tells its maker one true thing the zine did — the page that landed, the turn that surprised, the lettering they admired — in the hearing of the table, because a zine traded unread is a courtesy copy, and this workshop deals in readings. Zines may then be kept, re-traded along the table, or signed by their makers for their readers, as the room's customs emerge; the slate's catalogue is read aloud to close the round, every title and maker entire, the way a publisher's list is read — slowly enough to be a roll of honour, which it is.",
       "Closing the workshop, the archive copy and the next edition: each maker is invited — invited, not required — to leave one zine for the workshop's archive, the shelf or box where the session's publications live together, catalogued by the slate, borrowable by the room under the archive's one law (a borrowed zine is returned to its page of the catalogue, read, and never annotated). The tell-back is said with the trade table still holding its last unsold titles: 'This morning these were blank sheets, and a blank sheet promises nothing. They are publications now — folded, planned, lettered, sequenced and read entire by people who did not make them, whose praise you heard and whose copies are going home in their pockets. No editor passed them, no press printed them, and they are finished, which is the whole definition of the form. Eight pages, one sheet, no editor but the maker — and the maker, it turns out, was enough.' Practice sheets are recycled, the archive is shelved by the keeper, and the demonstrator — the adult's own twice-folded sheet — stays pinned where the next workshop will find the machinery already taught."],
      "A four-page version (a short session or a first workshop): the same sheet folded to four pages — cover, two inside, back — with the mapping, the making and the trading entire, because the discipline, not the page count, is the workshop.",
      "A themed-anthology version (a confident second workshop): every maker works the session's single theme, the trade table becomes an anthology reading, and the archive holds the set entire under one catalogue heading — eight views of one subject, bound by a table.",
      safety="The zine's one blade is the fold's single cut, and it is governed like the workshop's only machinery: the cut is made with the room's ordinary scissors, one cut per sheet, sheet flat on the table, cut away from the holding hand, and scissors travel closed and point-down or not at all — a maker who wants the cut made for them asks the adult or a neighbour, and the asking is ordinary workshop practice, not a lesser making. Pens are the session's chemistry, such as it is: water-based markers only, lids on between pages because a dried pen at page six is a production failure and a marked sleeve is a laundry failure, and any maker whose skin minds a pen works in the workshop's thin gloves or with the barrier the adult provides, without the matter becoming the table's conversation. Paper edges are the cut's other honesty: a freshly cut sheet can nip a finger like a letter opener, so sheets are handled by their folds during the making, and any cut finger — however small, however bravely reported — is washed and covered before the maker returns to a sheet that other hands will trade. The trade table's law is consent, stated in the framing's spirit and enforced plainly: a zine is read by its maker's leave, traded by its maker's leave, and archived only by its maker's leave.",
      copy_free=True, no_elimination=True,
      inclusion="Zine-making is hand-work at a table, and the workshop is seated entire without that costing any maker a thing: the fold is taught at the tables where makers sit, the demonstrator circulates to each table in turn, and the trade table is brought to browsing height for every reader in the room. Lettering welcomes every hand and every method: pens can be gripped fat or thin, pages can be lettered large where a maker's hand prefers it — a zine of few, big words per page is a recognised and honourable style of the form — and a maker may dictate their text to a scribe at their own table, who letters it verbatim and is credited on the colophon as the zine's letterer, because publishing has always divided conceiving from lettering and honoured both. The mapping stage is the workshop's great leveller: a plan can be drawn, described aloud to a map-checker, or built with the session's page tiles, and a map that another reader can follow is a passed map in any medium. During the trading round, zines can be read aloud by their makers or their booksellers at a browser's request, titles on the slate are read aloud entire as law, and no maker's standing in the catalogue depends on their handwriting's neatness, their reading voice, or their speed — only on the eight pages, finished, which the session's shape gives every maker the time to reach."),

    # ---------------- Holidays, just teens (holidays age-13/14 primary 9 -> 10) ----------------
    A("lunar-new-year-dumpling-folding-night", "Lunar New Year Dumpling Folding Night",
      "Teens host a dumpling night for the new year: folds sealed with water and patience, counted by the tray — the adult runs the steamer, the crew folds.",
      ["holidays"], (13, 14), (6, 20), (50, 60), ["indoor"],
      ["wrappers and filling, prepared with the adults in advance (round wrappers from a trusted shop, kept covered and damp; a filling the hosts have agreed — its ingredients listed entire on the night's card, its allergens checked against every guest and folder before the night is announced)", "the folding stations (a small bowl of water at each station for sealing, a floured tray per team for the finished work, a clean cloth over every tray of unfolded wrappers — the station is laid the same at every seat, because a right-handed room teaches left-handed folders nothing)", "the night's card (the filling's ingredients and allergens, the two sanctioned folds drawn step by step, the count the hosts are aiming for, and the steaming order — the night's whole law, read aloud at the framing)", "the tally board (trays counted as they fill, by team and in total — the night's arithmetic, kept by the hosts' tally-keeper, because a dumpling night that cannot say how many it folded has only made a mess with witnesses)"],
      False, "Plan the night backwards from the steamer, with the adult who will run it: how many dumplings the pot and steamer can honestly cook in the evening's rounds, how many guests will eat, and therefore how many the crew must fold — that number, with a margin for the learners' early casualties, is the night's aim, and it is set before a single wrapper is bought. Agree the filling with real care and write its card entire: ingredients, allergens, and the alternatives the night offers a guest who cannot eat it, because a feast whose card is vague is a feast some guests must watch. Lay the room as the folding will need it — stations in a row the adult can walk, water bowls filled, trays floured, wrappers still covered — and practise the two sanctioned folds yourself until your hands can teach them without your mouth: the half-moon pleat for the steamer and the simple sealed purse for the pot, each demonstrated at the framing from a folder's-eye view, slowly, twice. Learn the night's greeting properly, from a source that knows it, and how the festival is marked by the families who keep it — the hosts will speak of the new year with respect for a celebration that is theirs to join for an evening, not to borrow as decoration.",
      ["The framing, stations laid, wrappers covered, the night's card read aloud entire before a hand is wet: 'Every fold is a signature the steamer will read. Tonight we fold the new year in: dumplings folded by this crew, counted by the tray, cooked in rounds by the adult at the steamer — whose station is the adult's alone, because boiling water and steam do not take apprentices mid-service — and eaten together at the night's middle, not nibbled at the stations, because this is a feast with a shape, not a snack with a theme. The laws are a folder's laws. A dumpling is sealed or it is soup: the rim is wetted entire, the air is pressed out before the seal is closed, and a fold you would not sign goes back into the filling bowl at the practice tray, without ceremony, because the first six folds of any folder are tuition and the night has budgeted for them. Fill shy, seal sure: an ambitious dumpling bursts in the steamer and takes its neighbours' dignity with it, while a modest one, sealed true, is a small moon of a thing and eats like a feast. We greet the year properly, we fold it carefully, and we count it honestly. Wash your hands like you mean it — the night's first ceremony — and take your stations.' Hands are washed, stations are taken, and the two folds are demonstrated at folding distance before the first tray is opened.",
       "Folding school, the night's first quarter, run at the practice trays: the crew folds its tuition dumplings — filling, water, seal, pleat — with the demonstrators walking the row and correcting hands, not dumplings: a fold is fixed by teaching the fingers that made it, because a tray corrected by other hands teaches the original hands nothing. The school's standard is stated plainly and reached by nearly everyone inside the quarter: a dumpling that holds its seal under its own weight, lifted by its pleats, and keeps its filling when the tray is gently shaken. Folders who reach it early become the row's second demonstrators, named as such, because a folding night multiplies its teachers or it queues at one. The practice tray's casualties are counted by the tally-keeper with the same respect as the feast trays — the night's arithmetic includes its tuition, entered as tuition, because a count that hides its learners is a count that will hide anything.",
       "Production folding, the night's long middle, run by trays and rounds: teams fold to fill a tray, the tally-keeper counts each filled tray aloud and chalks it, and full trays travel to the steamer station by the route the adult walked at setup — two hands, at walking pace, never across the row's working elbows. The steamer's rounds set the night's pulse: while one tray cooks, the next fills, and the folding row learns the feast's oldest rhythm — work that is ready when the cooking needs it, neither rushed into bursting nor idled into drying. Wrappers are kept covered the whole night, a tray at a time exposed, because a dried wrapper cracks at the pleat and the crack is a leak the folder will be blamed for by a dumpling that never had a chance; the tally-keeper also keeps the wrapper count against the filling's level, calling the night's honest position at each steamer round — trays done, trays the filling can still honestly fill, and the moment to fold the last round and stop while the feast is ahead of the appetite, which is the tally's finest judgement.",
       "The feast, at the night's middle, eaten together as the framing promised: the crew washes hands again, the stations are cleared to serving, and the dumplings come from the steamer in their rounds to a table where folders and guests sit as one company. The night's card is read once more over the first tray — the filling, its allergens, the alternatives — so a guest eats with knowledge, not trust, and the alternatives arrive at the table with the same ceremony as the main dish, not as an apology after it. The hosts serve the first round and are served the second by the adult, because a crew that only serves has been staffed, not hosted, and tonight they are hosts. The tally-keeper chalks the feast's count entire before the eating starts — folded, steamed, and the practice tray's tuition beside them — and the new year is greeted properly by the whole table, in the words the hosts learned for the night, spoken like guests who were honoured to be taught them.",
       "Closing the night, the last tray and the count agreed: the final steamer round is folded from the filling's honest remainder — a small tray, folded at leisure, each dumpling pleated at its folder's best — and the night's closing count is agreed between tally-keeper and adult and chalked large: folded entire, eaten entire, tuition entire, three numbers that the night stands by. The tell-back is said at the cleared table, hands washed for the last time, bowls empty: 'This morning this night was a number on a card — how many a steamer can hold, how many a company can eat. It is a feast in the book now: folds taught hand to hand, seals that held, trays counted aloud, a year greeted in words we learned properly and meant. Every fold was a signature, and the steamer read them, and nearly every one of them held. Next year the crew that folds this night starts from our tally and our card, not from somebody's memory of a good evening. Folded, counted, eaten, written down — that is a night that happened.' The night's card is filed with the tally by the keeper, and the stations are washed by the crew that dirtied them, which is the feast's final law and its oldest one."],
      "A practice-only version (no feast, a class session): the crew folds one tray per team with a reusable practice filling of the adult's choosing, seals are tested in the steamer by the adult, and the night's school runs entire without the feast — the folds, the tally and the laws at teaching scale.",
      "A two-fold masterclass version (a returning crew): the night adds a third fold of the adult's choosing, the tally keeps a per-fold count, and the feast's first tray is folded entire in the new fold — a crew's second year, marked by a harder signature.",
      safety="Food sets this night's laws and they are read on the night's card before the framing ends: hands are washed with soap at the framing, after any break, and before the feast, without exception or abbreviation, and any folder with a cut on a working hand covers it or takes a non-food office for the night — the tally, the card, the greeting — at full standing. The filling's ingredients and allergens are checked against every folder and every guest before the night is announced, written entire on the card, and read aloud twice — at the framing and over the first tray — because an allergen announced once to a busy room is an allergen announced to half of it. All cooking is the adult's alone: the steamer, the pot, the boiling water and the steam are one station, worked by one adult, approached by the crew only along the walked route with a tray in two hands, and a tray is set down where the adult directs, never handed toward the steam. Raw and cooked never share a tray, a cloth or a pair of hands without washing between; filling stays covered and cold until the folding starts and the night's folding is brisk for that reason, not merely tidy. A dumpling that falls is compost, not a rescue; a folder who is unwell does not fold, and is given the night's honoured offices instead, because a feast's first ingredient is the health of its company.",
      tags=LUNAR, copy_free=True, no_elimination=True,
      inclusion="A folding row is a row of seated, skilled places, and the night staffs it as such: every station is a chair, a bowl and a tray at a height the folder chooses, the two folds are taught at folding distance at every seat — demonstrators walk the row rather than summoning folders to a front — and a fold can be learned from hands guided hand-over-hand, from the drawn card, or from a neighbour's repeated slow fold, all at identical standing. Folders work at their own honest pace inside the tray system, because the night is counted by trays, not by folders: a slow folder's tray is finished by the row without comment, a fast folder's hands are borrowed by the practice tray's teaching, and nobody's output is chalked by name — the tally boards count trays and totals, never people. The night's other offices are full honours: the tally-keeper holds the night's arithmetic and calls its position at every round, the card-reader reads the ingredients and allergens at the two ceremonies, and the greeter speaks the new year greeting for the table — each an office that can be held seated, standing, or in whatever register its holder commands, including read from the card by the keeper at the holder's request. Guests and folders who cannot eat the filling are planned for from the night's card onward, their alternative arriving with the feast's own ceremony — inclusion in this night is a menu decision made at planning, not an improvisation made at a table.")]

COLLECTION = {
    "id": "just-teens-third-time",
    "title": "Just Teens, a Third Time",
    "glyph": "🌔",
    "when_to_use": "The third shelf banded for thirteen- and fourteen-year-olds ONLY — the floor-raising shelf: seeds given their winter, a field line surveyed square by square, a long rope turned for everyone's courage, a choir holding two lines at once, a radio play recorded in one take per scene, an interview that introduces the person actually met, a whole publication folded from one sheet, and a new year folded in by the tray. Reach for it when the teen room needs the band's eight thinnest categories — seasons, outdoor, movement, music, rainy-day, icebreakers, crafts and holidays — written for the room itself, not borrowed from younger shelves.",
    "picks": [
        {"id": "cold-stratification-seed-bank", "note": "Cold is an ingredient, and the calendar is the recipe — jars of logged winter, weekly rounds, and a spring test that grades the bank in numbers."},
        {"id": "transect-line-field-survey", "note": "The line does not move; that is what makes it evidence — quadrats at fixed intervals, named only as far as the guide honestly carries."},
        {"id": "long-rope-turning-crew", "note": "The rope belongs to the turners; the jumping belongs to everyone — height, beat and rescue, with the crew's mark chalked honest, landed or not."},
        {"id": "part-singing-choir-first-rehearsals", "note": "Blending is listening louder than you sing — two lines learned apart until boring, then held together, falls and joins in the same log."},
        {"id": "foley-radio-play-recording", "note": "The audience believes its ears; the studio's job is to deserve that — actors, a hand-made Foley table, one take and at most one retake per scene."},
        {"id": "partner-portrait-interviews", "note": "You introduce the person you actually met, not the one you expected — three questions, a partner's own words on the card, and the right to strike any line."},
        {"id": "one-sheet-zine-workshop", "note": "Eight pages, one sheet, no editor but the maker — planned on the map, lettered in the flat order, and traded only after being read entire."},
        {"id": "lunar-new-year-dumpling-folding-night", "note": "Every fold is a signature the steamer will read — teens fold and tally by the tray, the adult alone runs the steamer, and the feast is eaten together."},
    ],
}


def tokens(s):
    return set(re.findall(r"[a-z0-9]+", s.lower()))


def main():
    path = os.path.join(DATA, "activities.json")
    acts = json.load(open(path))
    existing = {a["id"] for a in acts}
    corpus = [(a["id"], tokens(a["name"] + " " + a["tagline"])) for a in acts]
    for rec in PACK:
        t = tokens(rec["name"] + " " + rec["tagline"])
        worst, wid = 0.0, None
        for oid, ot in corpus:
            j = len(t & ot) / max(1, len(t | ot))
            if j > worst:
                worst, wid = j, oid
        print(f"jaccard {rec['id']}: worst {worst:.2f} vs {wid}")
        assert worst < 0.55, f"near-duplicate: {rec['id']} vs {wid} ({worst:.2f})"
        assert rec["age_min"] == 13 and rec["age_max"] == 14, f"not 13-14: {rec['id']}"
        assert len(rec["tagline"]) <= 160, f"tagline too long: {rec['id']} ({len(rec['tagline'])})"
        words = len(json.dumps(rec).split())
        print(f"words {rec['id']}: {words}")
        assert words >= 1300, f"record under the long-form bar: {rec['id']} ({words})"
    added = 0
    for rec in PACK:
        if rec["id"] in existing:
            print("skip (exists):", rec["id"])
            continue
        acts.append(rec)
        existing.add(rec["id"])
        added += 1
    json.dump(acts, open(path, "w"), indent=1, ensure_ascii=False)
    print(f"added {added} activities; total now {len(acts)}")

    cpath = os.path.join(DATA, "collections.json")
    cdata = json.load(open(cpath))
    colls = cdata["collections"]
    if COLLECTION["id"] not in {c["id"] for c in colls}:
        colls.append(COLLECTION)
        cdata["collections"] = colls
        json.dump(cdata, open(cpath, "w"), indent=1, ensure_ascii=False)
        print(f"collection added: {COLLECTION['id']} ({len(COLLECTION['picks'])} picks); collections now {len(colls)}")
    else:
        print("collection exists, skipped; collections:", len(colls))


if __name__ == "__main__":
    main()
